import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int q = nextInt();
        // Each bucket keeps the set of its distinct file names (insertion order kept).
        LinkedHashMap<String, HashSet<String>> buckets = new LinkedHashMap<>();
        String current = null;
        for (int i = 0; i < q; i++) {
            String op = next(), name = next();
            if (op.equals("goto")) {
                current = name;
                buckets.computeIfAbsent(name, k -> new HashSet<>());
            } else {
                buckets.get(current).add(name);
            }
        }
        String best = null;
        for (Map.Entry<String, HashSet<String>> e : buckets.entrySet())
            if (best == null || e.getValue().size() > buckets.get(best).size()) best = e.getKey();
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := nextInt()
	// Each bucket keeps the set of its distinct file names.
	buckets := map[string]map[string]struct{}{}
	order := []string{}
	current := ""
	for i := 0; i < q; i++ {
		op, name := string(token()), string(token())
		if op == "goto" {
			current = name
			if _, ok := buckets[name]; !ok {
				buckets[name] = map[string]struct{}{}
				order = append(order, name)
			}
		} else {
			buckets[current][name] = struct{}{}
		}
	}
	best := order[0]
	for _, name := range order {
		if len(buckets[name]) > len(buckets[best]) {
			best = name
		}
	}
	fmt.Println(best)
}
